#!/usr/bin/env python3
"""Copy the Spec Kit feature specifications into ThinkRail's spec-graph format under thinkrail/.

The constitution and the language specifications carry their own frontmatter and are nodes of the
spec graph in place, so they are not copied. The feature specifications have no frontmatter, so each
is copied here with one, as a child of the feature archive (`specs-archive`, in specs/SPEC.md).

The sources stay the truth: every file under thinkrail/ is generated from one source file,
which it copies verbatim after a YAML frontmatter (id, type, title, status, parent, references)
and a one-line note naming its source. Relative Markdown links are rewritten so they still
point at the files beside the source.

  python .github/scripts/thinkrail-specs.py          # write thinkrail/
  python .github/scripts/thinkrail-specs.py --check  # fail if thinkrail/ is out of date

Mapping:
  specs/NNN-name/<spec file>                    -> thinkrail/specs/NNN-name.md      task-spec
  specs/<repository>/NNN-name/<spec file>       -> thinkrail/specs/<repository>/NNN-name.md task-spec
"""

from __future__ import annotations

import json
import os
import posixpath
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "thinkrail"
SCRIPT = ".github/scripts/thinkrail-specs.py"

PARENT_ID = "specs-archive"

FRONTMATTER_ID = re.compile(r"\A---\r?\n(?:.*\r?\n)*?id:\s*(\S+)\s*\r?\n")

# Spec Kit companion status -> ThinkRail lifecycle status.
STATUS = {
    "completed": "done",
    "implemented": "done",
    "implementing": "active",
    "ready-to-implement": "active",
    "planned": "active",
    "specified": "draft",
    "draft": "draft",
}

# Short id prefix for the features kept per repository.
REPOSITORY_PREFIX = {
    "etalii.adp.ide.intellij": "intellij",
    "etalii.adp.site": "site",
}

# Words in a feature's folder name that tie it to a language specification.
LANGUAGE_HINTS = {
    "disl": "disl",
    "did": "did",
    "desl": "desl",
    "ded": "ded",
    "dedl": "ded",
    "fbl": "fbl",
    "format-binding": "fbl",
    "atd": "atd",
    "adp-tool-language": "atd",
}

LINK = re.compile(r"(\]\()([^)\s]+)((?:\s+\"[^\"]*\")?\))")


def yaml_str(value: str) -> str:
    return json.dumps(value, ensure_ascii=False)


def first_heading(text: str) -> str | None:
    in_comment = False
    for line in text.splitlines():
        if "<!--" in line and "-->" not in line.split("<!--", 1)[1]:
            in_comment = True
            continue
        if in_comment:
            if "-->" in line:
                in_comment = False
            continue
        if line.startswith("# "):
            return line[2:].strip()
    return None


def rewrite_links(text: str, source: Path, target: Path) -> str:
    """Point relative links in the copied body back at the files beside the source."""
    src_dir = source.parent.relative_to(ROOT).as_posix()
    tgt_dir = target.parent.relative_to(ROOT).as_posix()

    def fix(m: re.Match[str]) -> str:
        href = m.group(2)
        if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", href) or href.startswith(("#", "/", "<")):
            return m.group(0)
        path, sep, frag = href.partition("#")
        if not path:
            return m.group(0)
        resolved = posixpath.normpath(posixpath.join(src_dir, path))
        new = posixpath.relpath(resolved, tgt_dir)
        return f"{m.group(1)}{new}{sep}{frag}{m.group(3)}"

    out, fence = [], False
    for line in text.splitlines(keepends=True):
        if line.lstrip().startswith(("```", "~~~")):
            fence = not fence
        out.append(line if fence else LINK.sub(fix, line))
    return "".join(out)


def render(node: dict) -> str:
    source: Path = node["source"]
    target: Path = node["target"]
    text = source.read_text(encoding="utf-8")
    newline = "\r\n" if "\r\n" in text else "\n"
    fm = ["---", f"id: {node['id']}", f"type: {node['type']}", f"title: {yaml_str(node['title'])}"]
    if node.get("status"):
        fm.append(f"status: {node['status']}")
    if node.get("parent"):
        fm.append(f"parent: {node['parent']}")
    if node.get("references"):
        fm.append("references:")
        fm += [f"  - {r}" for r in node["references"]]
    if node.get("tags"):
        fm.append("tags:")
        fm += [f"  - {t}" for t in node["tags"]]
    fm.append("---")
    src_rel = source.relative_to(ROOT).as_posix()
    link = posixpath.relpath(src_rel, target.parent.relative_to(ROOT).as_posix())
    note = (
        f"> Generated copy of [`{src_rel}`]({link}) for ThinkRail's spec graph. "
        f"Edit the source and run `python {SCRIPT}`; do not edit this file."
    )
    body = rewrite_links(text, source, target)
    return newline.join(fm + ["", note, "", ""]) + body


def feature_spec_file(folder: Path) -> Path | None:
    candidates = sorted(folder.glob("*.spec.md")) or ([folder / "spec.md"] if (folder / "spec.md").exists() else [])
    return candidates[0] if candidates else None


def feature_status(folder: Path) -> str | None:
    ctx = folder / ".spec-context.json"
    if not ctx.exists():
        return None
    try:
        status = json.loads(ctx.read_text(encoding="utf-8")).get("status")
    except json.JSONDecodeError:
        return None
    if status and status not in STATUS:
        print(f"warning: unknown Spec Kit status {status!r} in {ctx.relative_to(ROOT).as_posix()}", file=sys.stderr)
    return STATUS.get(status)


def graph_ids() -> set[str]:
    """The ids of the spec-graph nodes that live in place, outside thinkrail/."""
    ids: set[str] = set()
    for dirpath, dirnames, filenames in os.walk(ROOT):
        dirnames[:] = [d for d in dirnames if not d.startswith(".git") and d not in {"node_modules", "thinkrail"}]
        for name in filenames:
            if name.endswith(".md"):
                with open(os.path.join(dirpath, name), encoding="utf-8", errors="replace") as f:
                    m = FRONTMATTER_ID.match(f.read(4096))
                if m:
                    ids.add(m.group(1))
    return ids


def language_refs(name: str, known: set[str]) -> list[str]:
    refs = []
    for word, lang in LANGUAGE_HINTS.items():
        if re.search(rf"(^|-){re.escape(word)}(-|$)", name) and lang in known and lang not in refs:
            refs.append(lang)
    return refs


def collect(known: set[str]) -> list[dict]:
    nodes: list[dict] = []
    specs = ROOT / "specs"
    for folder in sorted(specs.iterdir()):
        if not folder.is_dir():
            continue
        if re.match(r"^\d{3}-", folder.name):
            groups = [(folder, f"feature-{folder.name}", OUT / "specs" / f"{folder.name}.md", [])]
        elif folder.name in REPOSITORY_PREFIX:
            prefix = REPOSITORY_PREFIX[folder.name]
            groups = [
                (sub, f"{prefix}-{sub.name}", OUT / "specs" / folder.name / f"{sub.name}.md", [folder.name])
                for sub in sorted(folder.iterdir()) if sub.is_dir() and re.match(r"^\d{3}-", sub.name)
            ]
        else:
            continue
        for sub, node_id, target, tags in groups:
            source = feature_spec_file(sub)
            if source is None:
                print(f"warning: no spec file in {sub.relative_to(ROOT).as_posix()}", file=sys.stderr)
                continue
            title = first_heading(source.read_text(encoding="utf-8")) or sub.name
            title = re.sub(r"^Feature Specification:\s*", "", title)
            nodes.append({
                "id": node_id, "type": "task-spec", "source": source, "target": target,
                "title": f"{sub.name[:3]} {title}", "status": feature_status(sub),
                "parent": PARENT_ID, "references": language_refs(sub.name, known),
                "tags": ["spec-kit"] + tags,
            })
    return nodes


def validate(nodes: list[dict], known: set[str]) -> list[str]:
    errors, ids = [], dict.fromkeys(known)
    for n in nodes:
        if n["id"] in ids:
            errors.append(f"duplicate id {n['id']}")
        ids[n["id"]] = n
    for n in nodes:
        for link in ([n["parent"]] if n.get("parent") else []) + n.get("references", []):
            if link not in ids:
                errors.append(f"{n['id']}: dangling link {link}")
    return errors


def main() -> int:
    check = "--check" in sys.argv[1:]
    known = graph_ids()
    nodes = collect(known)
    errors = validate(nodes, known)
    if errors:
        print("\n".join(errors), file=sys.stderr)
        return 1
    expected = {n["target"]: render(n) for n in nodes}
    stale = []
    for target, content in expected.items():
        current = target.read_text(encoding="utf-8") if target.exists() else None
        if current != content:
            stale.append(target)
            if not check:
                target.parent.mkdir(parents=True, exist_ok=True)
                with open(target, "w", encoding="utf-8", newline="") as f:
                    f.write(content)
    extra = [p for p in OUT.rglob("*.md") if p not in expected and p.name != "README.md"] if OUT.exists() else []
    if not check:
        for p in extra:
            p.unlink()
    rel = lambda p: p.relative_to(ROOT).as_posix()  # noqa: E731
    if check:
        for p in stale:
            print(f"out of date: {rel(p)}", file=sys.stderr)
        for p in extra:
            print(f"no source: {rel(p)}", file=sys.stderr)
        if stale or extra:
            print(f"run: python {SCRIPT}", file=sys.stderr)
            return 1
        print(f"thinkrail/: {len(nodes)} specs up to date")
        return 0
    print(f"thinkrail/: {len(nodes)} specs, {len(stale)} written, {len(extra)} removed")
    return 0


if __name__ == "__main__":
    sys.exit(main())
